A sequent is \emph{valid} iff every \iftag{FOL}{!!{structure}~$\Struct
  M$}{!!{valuation}~$\pAssign{v}$} satisfies it.
\end{defn}

\begin{proof}
If $\Gamma \Proves !A$ then for some finite subset $\Gamma_0 \subseteq
\Gamma$, there is !!a{derivation} of $\Gamma_0 \Sequent !A$.  By
\olref{thm:sequent-soundness}, every
\iftag{FOL}{!!{structure}~$\Struct{M}$}{!!{valuation}~$\pAssign{v}$}
either makes some $!B \in \Gamma_0$ false or makes $!A$ true.  Hence,
if $\iftag{FOL}{\Sat{M}}{\pSat{v}}{\Gamma}$ then also
$\iftag{FOL}{\Sat{M}}{\pSat{v}}{!A}$.
\end{proof}

\begin{cor}
\ollabel{cor:consistency-soundness}
If $\Gamma$ is satisfiable, then it is consistent.
\end{cor}

\begin{defn}
\ollabel{defn:sat}
If $\Gamma$ is a set of !!{sentence}s~$\Gamma$, we say that
!!a{structure}~$\Struct M$ \emph{satisfies}~$\Gamma$,
$\Sat{M}{\Gamma}$, iff $\Sat{M}{!A}$ for all $!A \in \Gamma$.
\end{defn}

\begin{ex}
The language of set theory~$\Lang L_Z$ contains only the single
two-place !!{predicate}~$\in$.
\end{ex}

\begin{thm}
\ollabel{thm:fseq-frm-equiv}
$\Frm[L]$ is the set of all $\Lang L$-strings~$!A$ such that
there exists a formula formation sequence for~$!A$.
\end{thm}

\begin{prop}
\ollabel{prop:fseq-trm-equiv}
$\Trm[L]$ is the set of all $\Lang L$-strings $t$
such that there exists a term formation sequence for~$t$.
\end{prop}

A particularly interesting !!{structure} for $\Lang L_Z$ in which the
!!{element}s of the domain are actually sets, and the interpretation
of $\Obj \in$ actually is the relation ``$x$ is !!a{element} of~$y$''
is the !!{structure}~$\Struct{{HF}}$ of \emph{hereditarily finite sets}:
\begin{enumerate}
\item $\Domain{{{HF}}} = \emptyset \cup \Pow{\emptyset} \cup
  \Pow{\Pow{\emptyset}} \cup \Pow{\Pow{\Pow{\emptyset}}} \cup \dots$;
\item $\Assign{\Obj \in}{{{HF}}} = \Setabs{\tuple{x, y}}{x, y \in
  \Domain{{{HF}}}, x \in y}$.
\end{enumerate}
\end{ex}

