\begin{defn}
An \emph{ordered ring} is a commutative ring which is also equipped
with a total order relation, $\leq$, such that:
\begin{align*}
	a \leq b &\lif a + c \leq b + c\\
	(a \leq b \land 0 \leq c) &\lif a \times c \leq b \times c
\end{align*}
\end{defn}

This takes care of the integers. But now we need to show very similar
things of the rationals. In particular, we now need to show that the
rationals form an ordered \emph{field}, under our given definitions of
$+$, $\times$, and $\leq$:
\begin{defn}\ollabel{orderedfield}
An \emph{ordered field} is an ordered ring which also satisfies:
\begin{align*}
	\emph{Multiplicative Inverse}& & (\forall a \in S \setminus \{0\})(\exists b \in S) a\times b& = 1
\end{align*}
\end{defn}

Concerning \olref{closuresmallest}: quite generally, if $X
\in C$ then $\bigcap C \subseteq X$.
\end{proof}

\begin{defn}\ollabel{def:equivalenceclass}
Let $R \subseteq A^2$ be an equivalence relation. For each $x \in A$,
the \emph{equivalence class} of $x$ in~$A$ is the set $\equivrep{x}{R}
= \Setabs{y \in A}{Rxy}$. The \emph{quotient} of $A$ under~$R$ is
$\equivclass{A}{R} = \Setabs{\equivrep{x}{R}}{x \in A}$, i.e., the set
of these equivalence classes. 
\end{defn}

\begin{prop}
If $R \subseteq A^2$ is an equivalence relation, then $Rxy$ iff
$\equivrep{x}{R} = \equivrep{y}{R}$.
\end{prop}

\begin{prob}
Show that $\equiv_n$ is an equivalence relation, for any $n \in
\PosInt$, and that $\equivclass{\Nat}{\equiv_n}$ has exactly $n$ members.
\end{prob}

\begin{prob}
  Consider the less-than-or-equal-to relation~$\le$ on the set $\{1,
  2, 3, 4\}$ as a graph and draw the corresponding diagram.
\end{prob}

\begin{ex}
Let $S \subseteq \Int^2$ be the successor relation on~$\Int$, i.e.,
$S = \Setabs{\tuple{x, y} \in \Int^2}{x + 1 = y}$, so that $Sxy$ iff $x + 1 = y$.

\begin{ex}
Take the successor relation $S \subseteq \Int^2$. $S^2xy$ iff $x + 2 =
y$, $S^3xy$ iff $x + 3 = y$, etc. So $S^+xy$ iff $x + n = y$ for some
