\begin{defn}[Formula]
\ollabel{defn:formulas}
The set~$\Frm[L_0]$ of \emph{!!{formula}s} of propositional logic
is defined inductively as follows:
\begin{enumerate}
\tagitem{prvFalse}{$\lfalse$ is an atomic !!{formula}.}{}

\begin{defn}
  Given !!a{valuation}~$\pAssign{v}$, define the evaluation function
  $\pValue{v} \colon \Frm[L_0] \to \{\True, \False \}$ inductively by:
  \begin{align*}
    \iftag{prvFalse}{\pValue{v}(\lfalse) & = \False; \\}{}
    \iftag{prvTrue}{\pValue{v}(\ltrue) & = \True; \\}{}
    \pValue{v}(\Obj p_n) & = \pAssign{v}(\Obj p_n); \\
    \iftag{prvNot}{\pValue{v}(\lnot !A) & = \begin{cases}
        \True & \text{if } \pValue{v}(!A) = \False;\\
        \False & \text{otherwise.}
      \end{cases} \\ }{}
    \iftag{prvAnd}{\pValue{v}(!A \land !B) & = \begin{cases}
        \True &
        \text{if $\pValue{v}(!A) = \True$ and $\pValue{v}(!B) = \True$;}\\
        \False &
        \text{if $\pValue{v}(!A) = \False$ or $\pValue{v}(!B) = \False$}.
      \end{cases}\\}{}
    \iftag{prvOr}{\pValue{v}(!A \lor !B) & = \begin{cases}
        \True &
        \text{if $\pValue{v}(!A) = \True$ or $\pValue{v}(!B) = \True$;}\\
        \False &
        \text{if $\pValue{v}(!A) = \False$ and $\pValue{v}(!B) = \False$}.
      \end{cases}\\}{}
    \iftag{prvIf}{\pValue{v}(!A \lif !B) & = \begin{cases}
        \True &
        \text{if $\pValue{v}(!A) = \False$ or $\pValue{v}(!B) = \True$;}\\
        \False &
        \text{if $\pValue{v}(!A) = \True$ and $\pValue{v}(!B) = \False$}.
      \end{cases}\\}{}
    \iftag{prvIff}{\pValue{v}(!A \liff !B) & = \begin{cases}
        \True &
        \text{if $\pValue{v}(!A) = \pValue{v}(!B)$;}\\
        \False &
        \text{if $\pValue{v}(!A) \neq \pValue{v}(!B)$}.
      \end{cases}}{}
\end{align*}
\end{defn}

\begin{prob}
Consider adding to $\Lang{L_0}$ a ternary connective $\diamondsuit$
with evaluation given by
\begin{gather*}
  \pValue{v}(\diamondsuit( !A , !B , !C ) ) = \begin{cases}
    \pValue{v}( !B ) &
    \text{if $\pValue{v}(!A) = \True$;}\\
    \pValue{v}( !C ) &
    \text{if $\pValue{v}(!A) = \False $}.
  \end{cases}
\end{gather*}
Write down the truth table for this connective.
\end{prob}

This takes care of the integers. But now we need to show very similar
things of the rationals. In particular, we now need to show that the
rationals form an ordered \emph{field}, under our given definitions of
$+$, $\times$, and $\leq$:
\begin{defn}\ollabel{orderedfield}
An \emph{ordered field} is an ordered ring which also satisfies:
\begin{align*}
	\emph{Multiplicative Inverse}& & (\forall a \in S \setminus \{0\})(\exists b \in S) a\times b& = 1
\end{align*}
\end{defn}

Next, we must define some operations on the reals. We start by
embedding the rationals into the reals by stipulating that $p_\Real =
\Setabs{q \in \Rat}{q < p}$ for each $p \in \Rat$. We then define:
\begin{align*}
	\alpha + \beta &= \Setabs{p + q}{p \in \alpha \land q \in \beta}\\
%	\alpha - \beta &\defis \Setabs{p - q}{p \in \alpha \land q \in \Rat \setminus \beta}\\
	\alpha \times \beta &= 
	\Setabs{p \times q}{0 \leq p \in \alpha \land 0 \leq q \in \beta} \cup 0^\mathbb{R} & \text{if }\alpha, \beta \geq 0_\Real
%	\alpha \div \beta &\defis 
%	\Setabs{\nicefrac{p}{q}}{p \in \alpha \land q \in \Rat \setminus \beta}  & \text{if }\alpha \geq 0_\Real, \beta > 0_\Real
\end{align*}
To handle the other multiplication cases, first let: %that $0_\Real \times \alpha = 0_\Real = \alpha \times 0_\Real$, and add:
\begin{align*}
	-\alpha &= \Setabs{p - q}{p < 0 \land q \notin \alpha}
\end{align*}
and then stipulate:
\begin{align*}
	\alpha \times \beta &\defis 
	\begin{cases}
		\mathord{-}\alpha \times \mathord{-}\beta &\text{if }\alpha < 0_\Real\text{ and }\beta < 0_\Real\\
		\mathord{-}(\mathord{-}\alpha \times \beta) &\text{if }\alpha < 0_\Real \text{ and }\beta > 0_\Real\\
		\mathord{-}(\alpha \times \mathord{-}\beta) &\text{if }\alpha > 0_\Real \text{ and }\beta < 0_\Real
	\end{cases}
\end{align*}
We then need to check that each of these definitions always yields a
cut. And finally, we need to go through an easy (but long-winded)
demonstration that the cuts, so defined, behave exactly as they
should. But we relegate all of this to \olref[check]{sec}.

As with the integers, we also want to define some basic operations.
Where $\equivrep{i,j}{\Ratequiv}$ is the equivalence class under
$\Ratequiv$ with $\tuple{i, j}$ as !!a{element}, we say:
\begin{align*}
	\equivrep{a, b}{\Ratequiv} + \equivrep{c, d}{\Ratequiv} &= \equivrep{ad + bc,  bd}{\Ratequiv}\\
	\equivrep{a, b}{\Ratequiv} \times \equivrep{c, d}{\Ratequiv} &= \equivrep{a  c, b d}{\Ratequiv}.
\intertext{To define $r \leq s$ on these rationals, we use the fact that 
$r \le s$ iff $s - r$ is not negative, i.e., $r - s$ can be written as 
$\nicefrac{i}{j}$ with $i$ non-negative and $j$~positive:}
	\equivrep{a, b}{\Ratequiv} \leq \equivrep{c, d}{\Ratequiv} &\text{ iff }
	\equivrep{c, d}{\Ratequiv} - \equivrep{a, b}{\Ratequiv} = 
	\equivrep{i_\Int, j_\Int}{\Ratequiv}
\end{align*}
for some $i \in \Nat$ and $0 \neq j \in \Nat$.

\begin{ex}
Consider the functions $f(x) = x + 1$, and $g(x) = 2x$. Since
$(\comp{f}{g})(x) = g(f(x))$, for each input~$x$ you must first take
its successor, then multiply the result by two. So their composition
is given by $(\comp{f}{g})(x) = 2(x+1)$.
\end{ex}

\begin{proof}
By the definition of a Dedekind algebra, $N = \closureofunder{s}{o}$.
Now if both ${o} \in X$ and $(\forall {n} \in N)(n \in X \lif
{s}({n}) \in X)$, then $N = \closureofunder{s}{o} \subseteq X$.
\end{proof}

Now we stipulate that the hotel shall have infinitely many numbered
rooms $1$, $2$, $3$, $4$, $5$, \dots, each of which is occupied by
exactly one guest. As soon as a new guest comes along, the owner only
needs to move each of the old guests into the room associated with the
number one higher, and room~$1$ will be free for the newly-arriving
guest. 
	\begin{center}
		\begin{tikzpicture}[scale = .75]
		\foreach \x in {1, 2, 3, 4, 5, 6, 7, 8, 9}
		{
			\node (\x a) at (\x, 1) {\small{\x}};
			\node (\x b) at (\x, 2) {\small{\x}};
		}
		\node (dotsa) at (10, 1) {\small{\ldots}};
		\node (dotsb) at (10, 2) {\small{\ldots}};
		\draw[->] (1b)--(2a);
		\draw[->] (2b)--(3a);
		\draw[->] (3b)--(4a);
		\draw[->] (4b)--(5a);
		\draw[->] (5b)--(6a);
		\draw[->] (6b)--(7a);
		\draw[->] (7b)--(8a);
		\draw[->] (8b)--(9a);
		\draw[->] (9b)--(dotsa);
		\draw (1,1) circle (.4);
		\end{tikzpicture}
	\end{center}
	(published in \citealt[730]{EwaldSieg2013}; our translation)
\end{quote}
The crucial point is that Hilbert's Hotel has infinitely many rooms;
and we can take his explanation to define what it means to say this.
Indeed, this was Dedekind's approach (presented here, of course, with
massive anachronism; Dedekind's definition is from
\citeyear{Dedekind1888}):

\begin{ex}
Let $S \subseteq \Int^2$ be the successor relation on~$\Int$, i.e.,
$S = \Setabs{\tuple{x, y} \in \Int^2}{x + 1 = y}$, so that $Sxy$ iff $x + 1 = y$.

\begin{ex}
Take the successor relation $S \subseteq \Int^2$. $S^2xy$ iff $x + 2 =
y$, $S^3xy$ iff $x + 3 = y$, etc. So $S^+xy$ iff $x + n = y$ for some
$n \geq 1$. In other words, $S^+xy$ iff $x < y$, and $S^*xy$ iff $x \le
y$.
\end{ex}

\begin{prop}
If $\tuple{A,\le}$ is a tree, then every $x \in A$ other than the root
has at most one predecessor.
\end{prop}

\begin{defn}
A tree $T = \tuple{A, \le}$ is said to be \emph{infinite} if $A$ is an
infinite set, and \emph{finite} otherwise. If $T$ is such that every
$x \in A$ has only finitely many successors, then we say that $T$ is
\emph{finitely branching}.
\end{defn}

\begin{ex}
If $A$ is a set, the product of $A$ with itself, $A \times A$, is also
written~$A^2$. It is the set of \emph{all} pairs $\tuple{x, y}$ with
$x, y \in A$. The set of all triples $\tuple{x, y, z}$ is $A^3$, and
so on. We can give a recursive definition:
\begin{align*}
  A^1 & = A\\
  A^{k+1} & = A^k \times A
\end{align*}
\end{ex}

\begin{ex}
A function enumerating the natural numbers is simply the identity
function $\Id{\Nat} \colon \Nat \to \Nat$ given by $\Id{\Nat}(n) = n$. A
function enumerating the \emph{positive} natural numbers, $\Nat^+ =
\Nat \setminus \{0\}$, is the function $g(n) = n + 1$, i.e., the
successor function.
\end{ex}

