\begin{defn}
  Given !!a{valuation}~$\pAssign{v}$, define the evaluation function
  $\pValue{v} \colon \Frm[L_0] \to \{\True, \False \}$ inductively by:
  \begin{align*}
    \iftag{prvFalse}{\pValue{v}(\lfalse) & = \False; \\}{}
    \iftag{prvTrue}{\pValue{v}(\ltrue) & = \True; \\}{}
    \pValue{v}(\Obj p_n) & = \pAssign{v}(\Obj p_n); \\
    \iftag{prvNot}{\pValue{v}(\lnot !A) & = \begin{cases}
        \True & \text{if } \pValue{v}(!A) = \False;\\
        \False & \text{otherwise.}
      \end{cases} \\ }{}
    \iftag{prvAnd}{\pValue{v}(!A \land !B) & = \begin{cases}
        \True &
        \text{if $\pValue{v}(!A) = \True$ and $\pValue{v}(!B) = \True$;}\\
        \False &
        \text{if $\pValue{v}(!A) = \False$ or $\pValue{v}(!B) = \False$}.
      \end{cases}\\}{}
    \iftag{prvOr}{\pValue{v}(!A \lor !B) & = \begin{cases}
        \True &
        \text{if $\pValue{v}(!A) = \True$ or $\pValue{v}(!B) = \True$;}\\
        \False &
        \text{if $\pValue{v}(!A) = \False$ and $\pValue{v}(!B) = \False$}.
      \end{cases}\\}{}
    \iftag{prvIf}{\pValue{v}(!A \lif !B) & = \begin{cases}
        \True &
        \text{if $\pValue{v}(!A) = \False$ or $\pValue{v}(!B) = \True$;}\\
        \False &
        \text{if $\pValue{v}(!A) = \True$ and $\pValue{v}(!B) = \False$}.
      \end{cases}\\}{}
    \iftag{prvIff}{\pValue{v}(!A \liff !B) & = \begin{cases}
        \True &
        \text{if $\pValue{v}(!A) = \pValue{v}(!B)$;}\\
        \False &
        \text{if $\pValue{v}(!A) \neq \pValue{v}(!B)$}.
      \end{cases}}{}
\end{align*}
\end{defn}

\begin{prob}
Let $f(n) = 0$ for every $n$. Let $g(n) = \frac{1}{(n+1)^2}$. Show
that both are Cauchy sequences, and indeed that the limit of both
functions is $0$, so that also $f \sim_\Real g$. 
\end{prob}

We will hone in on the l.u.b., by approaching it simultaneously from
below and above. In particular, we define two functions, $f, g \colon
\Nat \to \Rat$, with the aim that $f$ will hone in on the l.u.b.\ from
above, and $g$ will hone on in it from below. We start by defining:
\begin{align*}
	f(0) &= p \\
	g(0) &= q
\end{align*}
Then, where $a_n = \frac{f(n) + g(n)}{2}$, let:\footnote{This is a
recursive definition. But we have not \emph{yet} given any reason to
think that recursive definitions are ok.}
\begin{align*}
	f(n+1) &=
	\begin{cases}
		a_n &\text{if }(\forall h \in S)\equivrep{h}{} \leq (a_n)_\Real\\
		f(n)&\text{otherwise}
	\end{cases}\\
	g(n+1) &=
	\begin{cases}
		a_n &\text{if }(\exists h \in S)\equivrep{h}{} \geq (a_n)_\Real\\
	 	g(n) &\text{otherwise}
	\end{cases}
\end{align*}
Both $f$ and $g$ are Cauchy sequences. (This can be checked fairly
easily, but we leave it as an exercise.) Note that the function $(f-g)$
tends to $0$, since the difference between $f$ and $g$ halves at each
step. Hence $\equivrep{f}{} = \equivrep{g}{}$.

