there are also functions which never map different inputs to the same
outputs. Such functions are called !!{injective}, and can be pictured
as in \olref{fig:injective}.
\begin{figure}
  \olasset{assets/diagrams/injective.tikz}
  \caption{!!^a{injective} function never maps two different
    arguments to the same value.}
  \ollabel{fig:injective}
\end{figure}
\end{explain}

\begin{explain}
It is sometimes useful to relax the definition of function so that it
is not required that the output of the function is defined for all
possible inputs. Such mappings are called \emph{partial functions}.
\end{explain}

\begin{ex}
A function enumerating the natural numbers is simply the identity
function $\Id{\Nat} \colon \Nat \to \Nat$ given by $\Id{\Nat}(n) = n$. A
function enumerating the \emph{positive} natural numbers, $\Nat^+ =
\Nat \setminus \{0\}$, is the function $g(n) = n + 1$, i.e., the
successor function.
\end{ex}

\begin{ex}
A function enumerating the positive integers ($\PosInt$) is simply the
identity function given by $f(n) = n$. A function enumerating the
natural numbers $\Nat$ is the function $g(n) = n - 1$.
\end{ex}

