\end{enumerate}
\end{proof}

\tagitem{prvEx}{%
  \iftag{probEx}{%
    \indcase!{!A}{\lexists[x][!B(x)]}{}}{%
    \indcase{!A}{\lexists[x][!B(x)]}{$\Sat{M(\Gamma^*)}{\indfrm}$ iff
      $\Sat{M(\Gamma^*)}{!B(t)}$ for at least one term~$t$
      (\olref{prop:quant-termmodel}).  By induction hypothesis, this
      is the case iff $!B(t) \in \Gamma^*$ for at least one term~$t$.
      By \olref[hen]{prop:saturated-instances}, this in turn is the
      case iff $\lexists[x][!B(x)] \in \Gamma^*$.}}}{}
}{}
\end{enumerate}
\end{proof}

\begin{prop}\ollabel{prop:saturated-instances}
Suppose $\Gamma$ is complete, consistent, and saturated.
\begin{tagenumerate}{prvEx,prvAll}
\tagitem{prvEx}{$\lexists[x][!A(x)] \in \Gamma$ iff $!A(t) \in \Gamma$
  for at least one closed term~$t$.}{}
\tagitem{prvAll}{$\lforall[x][!A(x)] \in \Gamma$ iff $!A(t) \in \Gamma$
  for all closed terms~$t$.}{}
\end{tagenumerate}
\end{prop}

\begin{prop}\ollabel{prop:saturated-instances}
Suppose $\Gamma$ is complete, consistent, and saturated.
\begin{tagenumerate}{prvEx,prvAll}
\tagitem{prvEx}{$\lexists[x][!A(x)] \in \Gamma$ iff $!A(t) \in \Gamma$
  for at least one closed term~$t$.}{}
\tagitem{prvAll}{$\lforall[x][!A(x)] \in \Gamma$ iff $!A(t) \in \Gamma$
  for all closed terms~$t$.}{}
\end{tagenumerate}
\end{prop}

\begin{prop}
\ollabel{prop:approx-equiv}
The relation $\approx$ has the following properties:
\begin{enumerate}
\item $\approx$ is reflexive.
\item $\approx$ is symmetric.
\item  $\approx$ is transitive.
\item If $t \approx t'$, $f$ is !!a{function}, and $t_1$, \dots,
  $t_{i-1}$, $t_{i+1}$, \dots, $t_n$ are closed terms, then
\[
\Atom{f}{t_1,\dots, t_{i-1}, t, t_{i+1}, \dots, t_n} \approx
\Atom{f}{t_1,\dots, t_{i-1}, t', t_{i+1}, \dots, t_n}.
\]
\item If $t \approx t'$, $R$ is !!a{predicate}, and $t_1$, \dots,
  $t_{i-1}$, $t_{i+1}$, \dots, $t_n$ are closed terms, then
\begin{multline*}
\Atom{R}{t_1,\dots, t_{i-1}, t, t_{i+1}, \dots, t_n} \in \Gamma^* \text{ iff } \\
\Atom{R}{t_1,\dots, t_{i-1}, t', t_{i+1}, \dots, t_n} \in \Gamma^*.
\end{multline*}
\end{enumerate}
\end{prop}

\begin{prop}
\ollabel{prop:approx-equiv}
The relation $\approx$ has the following properties:
\begin{enumerate}
\item $\approx$ is reflexive.
\item $\approx$ is symmetric.
\item  $\approx$ is transitive.
\item If $t \approx t'$, $f$ is !!a{function}, and $t_1$, \dots,
  $t_{i-1}$, $t_{i+1}$, \dots, $t_n$ are closed terms, then
\[
\Atom{f}{t_1,\dots, t_{i-1}, t, t_{i+1}, \dots, t_n} \approx
\Atom{f}{t_1,\dots, t_{i-1}, t', t_{i+1}, \dots, t_n}.
\]
\item If $t \approx t'$, $R$ is !!a{predicate}, and $t_1$, \dots,
  $t_{i-1}$, $t_{i+1}$, \dots, $t_n$ are closed terms, then
\begin{multline*}
\Atom{R}{t_1,\dots, t_{i-1}, t, t_{i+1}, \dots, t_n} \in \Gamma^* \text{ iff } \\
\Atom{R}{t_1,\dots, t_{i-1}, t', t_{i+1}, \dots, t_n} \in \Gamma^*.
\end{multline*}
\end{enumerate}
\end{prop}

\begin{defn}
Suppose $\Gamma^*$ is a consistent and !!{complete} set in a
language~$\Lang L$, $t$ is a closed term, and $\approx$ as in the
previous definition. Then:
\[
\equivrep{t}{\approx} = \Setabs{t'}{t'\in \Trm[L], t \approx t'}
\]
and $\equivclass{\Trm[L]}{\approx} = \Setabs{\equivrep{t}{\approx}}{t \in \Trm[L]}$.
\end{defn}

\begin{prop}
$\Struct{\equivclass{M}{\approx}}$ is well defined, i.e., if $t_1$,
  \dots, $t_n$, $t_1'$, \dots, $t_n'$ are closed terms,
  and $t_i \approx t_i'$ then
\begin{enumerate}
\item $\equivrep{\Atom{f}{t_1,\dots, t_n}}{\approx} =
    \equivrep{\Atom{f}{t_1',\dots, t_n'}}{\approx}$, i.e.,
  \[
  \Atom{f}{t_1,\dots, t_n} \approx \Atom{f}{t_1',\dots, t_n'}
  \]
  and
\item $\Sat{M}{\Atom{R}{t_1,\dots, t_n}}$ iff
  $\Sat{M}{\Atom{R}{t_1',\dots, t_n'}}$, i.e.,
  \[
    \Atom{R}{t_1,\dots, t_n} \in \Gamma^* \text{ iff }
    \Atom{R}{t_1',\dots, t_n'} \in \Gamma^*.
  \]
\end{enumerate}
\end{prop}

\begin{lem} 
\ollabel{lem:val-in-termmodel-factored} Let $\Struct M = \Struct M
 (\Gamma^*)$, then $\Value{t}{\equivclass{M}{\approx}} = \equivrep{t}
 {\approx}$.
\end{lem}
\begin{proof} 
The proof is similar to that of \olref[mod]{lem:val-in-termmodel}.
\end{proof}

\begin{ex}
If $s$ and $t$ are closed terms, then $!A(s), \eq[s][t] \Proves !A(t)$:
\begin{prooftree}
\AxiomC{$\eq[s][t]$}
\AxiomC{$!A(s)$}
\RightLabel{$\Elim{\eq}$}
\BinaryInfC{$!A(t)$}
\end{prooftree}
This may be familiar as the ``principle of substitutability of
identicals,'' or Leibniz' Law.
\end{ex}

\begin{explain}
Recall the convention that when $!A$ is !!a{formula} with the
!!{variable}~$x$ free, we indicate this by writing~$!A(x)$. In the
same context, $!A(t)$ then is short for~$\Subst{!A}{t}{x}$. So we
could also write the $\Intro\lexists$ rule as:
\begin{prooftree}
\AxiomC{$\Subst{!A}{t}{x}$}
\RightLabel{\Intro{\lexists}}
\UnaryInfC{$\lexists[x][!A]$}
\end{prooftree}
Note that $t$ may already occur in~$!A$, e.g., $!A$~might
be~$\Atom{\Obj P}{t,x}$.  Thus, inferring $\lexists[x][\Atom{\Obj
P}{t,x}]$ from~$\Atom{\Obj P}{t,t}$ is a correct application
of~$\Intro\lexists$---you may ``replace'' one or more, and not
necessarily all, occurrences of~$t$ in the premise by the bound
!!{variable}~$x$. However, the eigenvariable conditions in
$\Intro\lforall$ and~$\Elim\lexists$ require that the !!{constant}~$a$
does not occur in~$!A$. So, you cannot correctly infer
$\lforall[x][\Atom{\Obj P}{a,x}]$ from $\Atom{\Obj P}{a,a}$
using~$\Intro\lforall$.
\end{explain}

\begin{explain}
In \Intro{\lexists} and \Elim{\lforall} there are no restrictions, and
the term~$t$ can be anything, so we do not have to worry about any
conditions. On the other hand, in the \Elim{\lexists} and
\Intro{\lforall} rules, the eigenvariable condition requires that the
!!{constant}~$a$ does not occur anywhere in the conclusion or in an
!!{undischarged} assumption. The condition is necessary to ensure that
the system is sound, i.e., only !!{derive}s !!{sentence}s from
!!{undischarged} assumptions from which they follow. Without this
condition, the following would be allowed:
\begin{prooftree}
  \AxiomC{$\lexists[x][!A(x)]$}
  \AxiomC{$\Discharge{!A(a)}{1}$}
  \RightLabel{*\Intro{\lforall}}
  \UnaryInfC{$\lforall[x][!A(x)]$}
  \RightLabel{\Elim{\lexists}}
  \BinaryInfC{$\lforall[x][!A(x)]$}
\end{prooftree}
However, $\lexists[x][!A(x)] \Entails/ \lforall[x][!A(x)]$.

The $\Proves$ relation based on !!{tableau}s is defined as follows:
$\Gamma \Proves !A$ iff there is some finite set~$\Gamma_0 = \{!B_1,
\dots, !B_n\} \subseteq \Gamma$ such that there is a closed !!{tableau}
for the assumptions
\[
\{\sFmla{\False}{!A}, \sFmla{\True}{!B_1}, \dots, \sFmla{\True}{!B_n}\} 
\]
For instance, here is a closed !!{tableau} that shows that $\Proves
(!A \land !B) \lif !A$:
\begin{oltableau}
  [\sFmla{\False}{(\formula{A} \land \formula{B}) \lif \formula{A}}, just = \TAss
    [\sFmla{\True}{\formula{A} \land \formula{B}}, just = {\TRule{\False}{\lif}[1]}
      [\sFmla{\False}{\formula{A}}, just = {\TRule{\False}{\lif}[1]}
        [\sFmla{\True}{\formula{A}}, just = {\TRule{\True}{\lif}[2]}
          [\sFmla{\True}{\formula{B}}, just = {\TRule{\True}{\lif}[2]}, close]
        ]
      ]
    ]
  ]
\end{oltableau}

The $\Proves$ relation based on !!{tableau}s is defined as follows:
$\Gamma \Proves !A$ iff there is some finite set~$\Gamma_0 = \{!B_1,
\dots, !B_n\} \subseteq \Gamma$ such that there is a closed !!{tableau}
for the assumptions
\[
\{\sFmla{\False}{!A}, \sFmla{\True}{!B_1}, \dots, \sFmla{\True}{!B_n}\} 
\]
For instance, here is a closed !!{tableau} that shows that $\Proves
(!A \land !B) \lif !A$:
\begin{oltableau}
  [\sFmla{\False}{(\formula{A} \land \formula{B}) \lif \formula{A}}, just = \TAss
    [\sFmla{\True}{\formula{A} \land \formula{B}}, just = {\TRule{\False}{\lif}[1]}
      [\sFmla{\False}{\formula{A}}, just = {\TRule{\False}{\lif}[1]}
        [\sFmla{\True}{\formula{A}}, just = {\TRule{\True}{\lif}[2]}
          [\sFmla{\True}{\formula{B}}, just = {\TRule{\True}{\lif}[2]}, close]
        ]
      ]
    ]
  ]
\end{oltableau}

\begin{defn}[Initial sequents for $\eq$]
If $t$ is a closed term, then ${} \Sequent \eq[t][t]$ is an initial sequent.
\end{defn}

\begin{ex}
If $s$ and $t$ are closed terms, then $\eq[s][t], !A(s)
\Proves !A(t)$:
\begin{prooftree}
\Axiom$ !A(s) \fCenter !A(s)$
\RightLabel{\LeftR{\Weakening}}
\UnaryInf$\eq[s][t], !A(s)  \fCenter !A(s)$
\RightLabel{$\eq$}
\UnaryInf$\eq[s][t], !A(s)  \fCenter !A(t)$
\end{prooftree}
This may be familiar as the principle of substitutability of
identicals, or Leibniz' Law.

In \LeftR{\lforall}, $t$ is a closed term (i.e., one without
variables). In \RightR{\lforall}, $a$~is !!a{constant} which must not
occur anywhere in the lower sequent of the \RightR{\lforall} rule. We
call $a$ the \emph{eigenvariable} of the \RightR{\forall}
inference.\footnote{We use the term ``eigenvariable'' even though $a$
in the above rule is !!a{constant}. This has historical reasons.}

\begin{explain}
In \RightR{\lexists} and \LeftR{\lforall} there are no restrictions on
the term~$t$. On the other hand, in the \LeftR{\lexists} and
\RightR{\lforall} rules, the eigenvariable condition requires that the
!!{constant}~$a$ does not occur anywhere outside of~$!A(a)$ in the
upper sequent. It is necessary to ensure that the system is sound,
i.e., only !!{derive}s sequents that are valid. Without this
condition, the following would be allowed:
\begin{prooftree}
  \Axiom$!A(a) \fCenter !A(a)$
  \RightLabel{*\LeftR{\lexists}}
  \UnaryInf$\lexists[x][!A(x)] \fCenter !A(a)$
  \RightLabel{\RightR{\lforall}}
  \UnaryInf$\lexists[x][!A(x)] \fCenter \lforall[x][!A(x)]$
  \DisplayProof\bottomAlignProof
  \qquad
  \Axiom$!A(a) \fCenter !A(a)$
  \RightLabel{*\RightR{\lforall}}
  \UnaryInf$!A(a) \fCenter \lforall[x][!A(x)]$
  \RightLabel{\LeftR{\lexists}}
  \UnaryInf$\lexists[x][!A(x)] \fCenter \lforall[x][!A(x)]$
\end{prooftree}
However, $\lexists[x][!A(x)] \Sequent \lforall[x][!A(x)]$ is not valid.
\end{explain}

\begin{explain}
Recall that a term is \emph{closed} if it contains no !!{variable}s.
\end{explain}

\begin{tagblock}{defNot,defOr,defAnd,defIf,defIff,defTrue,defFalse,defEx,defAll}
\begin{explain}
A defined symbol is not officially part of the language, but is
introduced as an informal abbreviation: it allows us to abbreviate
formulas which would, if we only used primitive symbols, get quite
long.  This is obviously an advantage.  The bigger advantage, however,
is that proofs become shorter.  If a symbol is primitive, it has to be
treated separately in proofs. The more primitive symbols, therefore,
the longer our proofs.
\end{explain}
\end{tagblock}

