Suppose the last inference in !!a{derivation} is \Elim{\eq}, i.e., the
!!{derivation} has the following form:
\begin{prooftree}
  \AxiomC{$\Gamma_1$}
  \RightLabel{$\delta_1$}
  \DeduceC{$\eq[t_1][t_2]$}
  \AxiomC{$\Gamma_2$}
  \RightLabel{$\delta_2$}
  \DeduceC{$!A(t_1)$}
  \RightLabel{\Elim{\eq}}
  \BinaryInfC{$!A(t_2)$}
\end{prooftree}
The premises $\eq[t_1][t_2]$ and $!A(t_1)$ are !!{derive}d from
!!{undischarged} assumptions~$\Gamma_1$ and $\Gamma_2$, respectively.
We want to show that $!A(t_2)$ follows from $\Gamma_1 \cup \Gamma_2$.
Consider !!a{structure}~$\Struct{M}$ with $\Sat{M}{\Gamma_1 \cup
  \Gamma_2}$. By induction hypothesis, $\Sat{M}{!A(t_1)}$ and
$\Sat{M}{\eq[t_1][t_2]}$. Therefore, $\Value{t_1}{M} = \Value{t_2}{M}$. Let
$s$ be any variable assignment, and $m = \Value{t_1}{M} = \Value{t_2}{M}$. By
\olref[fol][syn][ext]{prop:ext-formulas}, $\Sat{M}{!A(t_1)}[s]$ iff
$\Sat{M}{!A(x)}[\Subst{s}{m}{x}]$ iff $\Sat{M}{!A(t_2)}[s]$. Since
$\Sat{M}{!A(t_1)}$, we have $\Sat{M}{!A(t_2)}$.
\end{proof}

\iftag{FOL}{
\item The last inference is \Intro{\lforall}: Then $\delta$ has the form
  \begin{prooftree}
    \AxiomC{$\Gamma$}
    \RightLabel{$\delta_1$}
    \DeduceC{$!A(a)$}
    \RightLabel{\Intro{\lforall}}
    \UnaryInfC{$\lforall[x][!A(x)]$}
  \end{prooftree}
  The premise $!A(a)$ is a consequence of the !!{undischarged}
  assumptions $\Gamma$ by induction hypothesis.  Consider some
  structure, $\Struct{M}$, such that $\Sat{M}{\Gamma}$.  We need to
  show that $\Sat{M}{\lforall[x][!A(x)]}$. Since $\lforall[x][!A(x)]$
  is !!a{sentence}, this means we have to show that for every variable
  assignment~$s$, $\Sat{M}{!A(x)}[s]$
  (\olref[syn][ass]{prop:sat-quant}). Since $\Gamma$ consists entirely
  of sentences, $\Sat{M}{!B}[s]$ for all $!B \in \Gamma$ by
  \olref[syn][sat]{defn:satisfaction}.  Let $\Struct{M'}$ be like
  $\Struct{M}$ except that $\Assign{a}{M'} = s(x)$.  Since $a$ does
  not occur in~$\Gamma$, $\Sat{M'}{\Gamma}$ by
  \olref[syn][ext]{cor:extensionality-sent}. Since $\Gamma \Entails
  !A(a)$, $\Sat{M'}{!A(a)}$.  Since $!A(a)$ is !!a{sentence},
  $\Sat{M'}{!A(a)}[s]$ by
  \olref[syn][ass]{prop:sentence-sat-true}. $\Sat{M'}{!A(x)}[s]$ iff
  $\Sat{M'}{!A(a)}$ by \olref[syn][ext]{prop:ext-formulas} (recall
  that $!A(a)$ is just $\Subst{!A(x)}{a}{x}$). So,
  $\Sat{M'}{!A(x)}[s]$. Since $a$ does not occur in~$!A(x)$, by
  \olref[syn][ext]{prop:extensionality}, $\Sat{M}{!A(x)}[s]$. But $s$
  was an arbitrary variable assignment, so
  $\Sat{M}{\lforall[x][!A(x)]}$.

\iftag{FOL}{
\item The last inference is \Intro{\lforall}: Then $\delta$ has the form
  \begin{prooftree}
    \AxiomC{$\Gamma$}
    \RightLabel{$\delta_1$}
    \DeduceC{$!A(a)$}
    \RightLabel{\Intro{\lforall}}
    \UnaryInfC{$\lforall[x][!A(x)]$}
  \end{prooftree}
  The premise $!A(a)$ is a consequence of the !!{undischarged}
  assumptions $\Gamma$ by induction hypothesis.  Consider some
  structure, $\Struct{M}$, such that $\Sat{M}{\Gamma}$.  We need to
  show that $\Sat{M}{\lforall[x][!A(x)]}$. Since $\lforall[x][!A(x)]$
  is !!a{sentence}, this means we have to show that for every variable
  assignment~$s$, $\Sat{M}{!A(x)}[s]$
  (\olref[syn][ass]{prop:sat-quant}). Since $\Gamma$ consists entirely
  of sentences, $\Sat{M}{!B}[s]$ for all $!B \in \Gamma$ by
  \olref[syn][sat]{defn:satisfaction}.  Let $\Struct{M'}$ be like
  $\Struct{M}$ except that $\Assign{a}{M'} = s(x)$.  Since $a$ does
  not occur in~$\Gamma$, $\Sat{M'}{\Gamma}$ by
  \olref[syn][ext]{cor:extensionality-sent}. Since $\Gamma \Entails
  !A(a)$, $\Sat{M'}{!A(a)}$.  Since $!A(a)$ is !!a{sentence},
  $\Sat{M'}{!A(a)}[s]$ by
  \olref[syn][ass]{prop:sentence-sat-true}. $\Sat{M'}{!A(x)}[s]$ iff
  $\Sat{M'}{!A(a)}$ by \olref[syn][ext]{prop:ext-formulas} (recall
  that $!A(a)$ is just $\Subst{!A(x)}{a}{x}$). So,
  $\Sat{M'}{!A(x)}[s]$. Since $a$ does not occur in~$!A(x)$, by
  \olref[syn][ext]{prop:extensionality}, $\Sat{M}{!A(x)}[s]$. But $s$
  was an arbitrary variable assignment, so
  $\Sat{M}{\lforall[x][!A(x)]}$.

\begin{cor}
\ollabel{cor:sat-sentence}
If $!A$ is !!a{sentence} and $s$ a variable assignment, then
$\Sat{M}{!A}[s]$ iff $\Sat{M}{!A}[s']$ for every variable
assignment~$s'$.
\end{cor}

\begin{cor}
\ollabel{cor:sat-sentence}
If $!A$ is !!a{sentence} and $s$ a variable assignment, then
$\Sat{M}{!A}[s]$ iff $\Sat{M}{!A}[s']$ for every variable
assignment~$s'$.
\end{cor}

\begin{defn}
\ollabel{defn:satisfaction}
If $!A$ is !!a{sentence}, we say that !!a{structure}~$\Struct M$
\emph{satisfies}~$!A$, $\Sat{M}{!A}$, iff $\Sat{M}{!A}[s]$ for all
variable assignments~$s$.
\end{defn}

\begin{prop}\ollabel{prop:sentence-sat-true}
  Let $\Struct{M}$ be !!a{structure}, $!A$ be !!a{sentence}, and $s$ a
  variable assignment.  $\Sat{M}{!A}$ iff $\Sat{M}{!A}[s]$.
\end{prop}

\begin{prop}\ollabel{prop:sat-quant}
  Suppose $!A(x)$ only contains $x$ free, and $\Struct M$ is
  !!a{structure}. Then:
  \begin{tagenumerate}{prvEx,prvAll}
    \tagitem{prvEx}{$\Sat{M}{\lexists[x][!A(x)]}$ iff $\Sat{M}{!A(x)}[s]$
      for at least one variable assignment~$s$.}{}
    \tagitem{prvAll}{$\Sat{M}{\lforall[x][!A(x)]}$ iff $\Sat{M}{!A(x)}[s]$
  for all variable assignments~$s$.}{}
\end{tagenumerate}
\end{prop}

\begin{prop}\ollabel{prop:sat-quant}
  Suppose $!A(x)$ only contains $x$ free, and $\Struct M$ is
  !!a{structure}. Then:
  \begin{tagenumerate}{prvEx,prvAll}
    \tagitem{prvEx}{$\Sat{M}{\lexists[x][!A(x)]}$ iff $\Sat{M}{!A(x)}[s]$
      for at least one variable assignment~$s$.}{}
    \tagitem{prvAll}{$\Sat{M}{\lforall[x][!A(x)]}$ iff $\Sat{M}{!A(x)}[s]$
  for all variable assignments~$s$.}{}
\end{tagenumerate}
\end{prop}

(This problem shows that it is possible to give a semantics for
first-order logic that makes do without variable assignments.)
\end{prob}

\begin{prop}\ollabel{prop:ext-terms}
Let $\Struct M$ be !!a{structure}, $t$ and $t'$ terms, and $s$ a
variable assignment. Then $\Value{\Subst{t}{t'}{x}}{M}[s] =
\Value{t}{M}[\Subst{s}{\Value{t'}{M}[s]}{x}]$.
\end{prop}

\begin{defn}[Variable Assignment]
A \emph{variable assignment}~$s$ for !!a{structure}~$\Struct{M}$ is a
function which maps each !!{variable} to !!a{element} of~$\Domain M$,
i.e., $s\colon \Var \to \Domain M$.
\end{defn}

\begin{defn}[Variable Assignment]
A \emph{variable assignment}~$s$ for !!a{structure}~$\Struct{M}$ is a
function which maps each !!{variable} to !!a{element} of~$\Domain M$,
i.e., $s\colon \Var \to \Domain M$.
\end{defn}

\begin{defn}
  If $s$ is !!a{variable} assignment for !!a{structure}~$\Struct M$
  and $m \in \Domain{M}$, then the assignment~$\Subst{s}{m}{x}$ is the
  variable assignment defined by
  \[\Subst{s}{m}{x}(y) = \begin{cases}
    m & \text{if } y \ident x\\
    s(y) & \text{otherwise}.
  \end{cases}\]
\end{defn}

